import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys/values on the defaults mode=fast and level=3.

    Returns the resulting values in the order mode, level, then any other
    keys in the order given. keys[i] is set to values[i].
    """
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for key, value in zip(keys, values, strict=True):
        merged[key] = value
    return list(merged.values())


def test_settings_no_overrides() -> None:
    assert settings([], []) == ["fast", "3"]


def test_settings_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_settings_override_level() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_settings_extra_key_after_defaults() -> None:
    assert settings(["color", "mode"], ["red", "safe"]) == ["safe", "3", "red"]


def test_settings_extra_key_between_defaults() -> None:
    assert settings(["x", "level", "y"], ["1", "7", "2"]) == ["fast", "7", "1", "2"]
